{
  "story": "How do two features become regions? Start with Samples inside Root. A prescribed Vertical cut creates Left and Right. A prescribed Left cut divides only Left into Lower-left and Upper-left. Left cut stops at Vertical cut, leaving Right whole. Use Previous and Next; counts and impurity reveal how local splits build regions.",
  "aha": {
    "stateId": "local-split",
    "observation": "Each split cuts only its current region; Left cut stops at Vertical cut, leaving Right unchanged."
  },
  "layout": {
    "preset": "stepper-states",
    "width": 640
  },
  "parts": [
    {
      "id": "growth-rail",
      "kind": "step-rail",
      "presentation": "Place below the story and above the experiment. Show the active state and completed states here, without a separate timeline. Step positions represent states, not elapsed time.",
      "bind": {
        "active": "state.id",
        "items": "variant.states"
      }
    },
    {
      "id": "feature-plane",
      "kind": "fixed-picture",
      "presentation": "Use the tested fixed-picture part with a stationary feature plane. Horizontal axis is x₁; vertical axis is x₂. Both axes span zero through seven with equal unit spacing. Sample feature values determine marker placement; region predicates determine partition membership. Samples a–h remain visible in every state. Show partition regions and cuts only when active. Render cuts within their declared scope, never beyond it. Keep partition labels inside their regions without covering samples. Distinguish classes using both marker shape and letter. Cut labels identify boundaries; readouts report thresholds. Preserve label space at native width.",
      "bind": {
        "active": "state.active",
        "links": "variant.links",
        "regions": "variant.regions"
      }
    },
    {
      "id": "location-callout",
      "kind": "active-callout",
      "presentation": "Anchor the callout to its named target without covering markers. Use text to identify where the change occurs. Render reason as the bound status line.",
      "bind": {
        "target": "state.calloutRegion",
        "text": "state.sentence",
        "reason": "state.why"
      }
    },
    {
      "id": "partition-evidence",
      "kind": "value-readout",
      "presentation": "Place compact readout rows below the picture. Counts are exact; impurity and decreases are dimensionless and rounded to three decimals. Compute every count and impurity from the fixed sample values and active partition predicates. Gini uses class proportions within each region. Tree impurity weights leaf impurity by its fraction of all samples. Readouts own numeric evidence; callouts contain no duplicate measurements. Retained boundaries and fixed Samples provide comparison without a previous-state ghost.",
      "bind": {
        "values": "state.readouts"
      }
    }
  ],
  "controls": [
    {
      "id": "step",
      "kind": "index",
      "items": "variant.states",
      "label": "Partition state",
      "presentation": "Use Previous and Next, retaining those names when disabled. Default index is zero; bounds are zero through two; increment is one. Each action changes the partition evidence, not merely its label. Every state persists until another learner action; there is no timed playback. Reference captures show local-split. Provide accessible button names, visible focus, and standard keyboard operation. Detailed parameter-control budget: zero; navigation and reset are separate."
    },
    {
      "id": "reset",
      "kind": "reset",
      "label": "Reset",
      "presentation": "Restore the first state and all fixed defaults. Provide an accessible name, visible focus, and Enter or Space activation."
    }
  ],
  "data": {
    "variants": [
      {
        "label": "Two prescribed, axis-aligned splits",
        "regions": [
          {
            "id": "a",
            "label": "a · A",
            "values": ["x₁=1", "x₂=1", "class=A"]
          },
          {
            "id": "b",
            "label": "b · A",
            "values": ["x₁=2", "x₂=2", "class=A"]
          },
          {
            "id": "c",
            "label": "c · B",
            "values": ["x₁=1", "x₂=5", "class=B"]
          },
          {
            "id": "d",
            "label": "d · B",
            "values": ["x₁=2", "x₂=6", "class=B"]
          },
          {
            "id": "e",
            "label": "e · B",
            "values": ["x₁=5", "x₂=1", "class=B"]
          },
          {
            "id": "f",
            "label": "f · B",
            "values": ["x₁=6", "x₂=2", "class=B"]
          },
          {
            "id": "g",
            "label": "g · B",
            "values": ["x₁=5", "x₂=5", "class=B"]
          },
          {
            "id": "h",
            "label": "h · B",
            "values": ["x₁=6", "x₂=6", "class=B"]
          },
          {
            "id": "root",
            "label": "Root",
            "values": ["predicate: all Samples"]
          },
          {
            "id": "vertical-cut",
            "label": "Vertical cut",
            "values": [
              "feature: x₁",
              "threshold: 3",
              "scope: Root",
              "rule: ≤ enters Left; > enters Right"
            ]
          },
          {
            "id": "left",
            "label": "Left",
            "values": ["predicate: x₁ ≤ 3", "parent: Root"]
          },
          {
            "id": "right",
            "label": "Right",
            "values": ["predicate: x₁ > 3", "parent: Root"]
          },
          {
            "id": "left-cut",
            "label": "Left cut",
            "values": [
              "feature: x₂",
              "threshold: 3",
              "scope: Left",
              "rule: ≤ enters Lower-left; > enters Upper-left"
            ]
          },
          {
            "id": "lower-left",
            "label": "Lower-left",
            "values": [
              "predicate: x₁ ≤ 3 and x₂ ≤ 3",
              "parent: Left"
            ]
          },
          {
            "id": "upper-left",
            "label": "Upper-left",
            "values": [
              "predicate: x₁ ≤ 3 and x₂ > 3",
              "parent: Left"
            ]
          }
        ],
        "links": [],
        "states": [
          {
            "id": "unsplit",
            "label": "Root",
            "short": "One region",
            "sentence": "Root covers the entire feature plane.",
            "why": "Status: all Samples share Root; feature positions and class labels stay fixed.",
            "active": ["root"],
            "calloutRegion": "root",
            "readouts": [
              {
                "id": "assumptions",
                "label": "Fixed setup",
                "value": "Unitless features; no missing values; prescribed cuts; ≤ and > assign every sample uniquely."
              },
              {
                "id": "decision",
                "label": "Current decision",
                "value": "No cut yet."
              },
              {
                "id": "counts",
                "label": "Leaf counts (A, B)",
                "value": "Root: (2, 6)"
              },
              {
                "id": "gini",
                "label": "Gini = 1 − p(A)² − p(B)²",
                "value": "Root: 1 − (2/8)² − (6/8)² = 0.375"
              },
              {
                "id": "tree-impurity",
                "label": "Tree impurity I = Σleaf (nleaf/N)Gini",
                "value": "(8/8) × 0.375 = 0.375"
              },
              {
                "id": "decrease",
                "label": "Impurity decrease",
                "value": "Baseline; no split."
              }
            ]
          },
          {
            "id": "root-split",
            "label": "Vertical cut",
            "short": "Two regions",
            "sentence": "Vertical cut creates Left and Right across Root.",
            "why": "Status: both children inherit samples by feature value; every sample belongs to exactly one child.",
            "active": ["vertical-cut", "left", "right"],
            "calloutRegion": "vertical-cut",
            "readouts": [
              {
                "id": "assumptions",
                "label": "Fixed setup",
                "value": "Unitless features; no missing values; prescribed cuts; ≤ and > assign every sample uniquely."
              },
              {
                "id": "decision",
                "label": "Current decision",
                "value": "Within Root: x₁ ≤ 3 versus x₁ > 3."
              },
              {
                "id": "counts",
                "label": "Leaf counts (A, B)",
                "value": "Left: (2, 2); Right: (0, 4)"
              },
              {
                "id": "gini",
                "label": "Gini = 1 − p(A)² − p(B)²",
                "value": "Left: 0.500; Right: 0.000"
              },
              {
                "id": "tree-impurity",
                "label": "Tree impurity I = Σleaf (nleaf/N)Gini",
                "value": "(4/8) × 0.500 + (4/8) × 0.000 = 0.250"
              },
              {
                "id": "decrease",
                "label": "Impurity decrease",
                "value": "Root and whole tree: 0.375 − 0.250 = 0.125"
              }
            ]
          },
          {
            "id": "local-split",
            "label": "Left cut",
            "short": "Three regions",
            "sentence": "Left cut stops at Vertical cut; Right remains whole.",
            "why": "Status: Lower-left and Upper-left replace Left; Right keeps its original samples.",
            "active": [
              "vertical-cut",
              "left-cut",
              "lower-left",
              "upper-left",
              "right"
            ],
            "calloutRegion": "left-cut",
            "readouts": [
              {
                "id": "assumptions",
                "label": "Fixed setup",
                "value": "Unitless features; no missing values; prescribed cuts; ≤ and > assign every sample uniquely."
              },
              {
                "id": "decision",
                "label": "Current decision",
                "value": "Within Left only: x₂ ≤ 3 versus x₂ > 3."
              },
              {
                "id": "counts",
                "label": "Leaf counts (A, B)",
                "value": "Lower-left: (2, 0); Upper-left: (0, 2); Right: (0, 4)"
              },
              {
                "id": "gini",
                "label": "Gini = 1 − p(A)² − p(B)²",
                "value": "Every leaf: 0.000"
              },
              {
                "id": "tree-impurity",
                "label": "Tree impurity I = Σleaf (nleaf/N)Gini",
                "value": "(2/8) × 0 + (2/8) × 0 + (4/8) × 0 = 0.000"
              },
              {
                "id": "decrease",
                "label": "Impurity decrease",
                "value": "Within Left: 0.500; whole tree: (4/8) × 0.500 = 0.250"
              }
            ]
          }
        ]
      }
    ]
  }
}
